const page = await fetchText(sourceUrl);
let items = parseFeed(page.body, page.url, page.contentType);

if (!items) {
  const feedUrl = discoverFeed(page.body, page.url);
  if (feedUrl) {
    try {
      const feed = await fetchText(feedUrl);
      items = parseFeed(feed.body, feed.url, feed.contentType);
    } catch {
      // Fall back to parsing the source page as HTML.
    }
  }
}

const normalized = normalizeItems(
  items ?? parseHtml(page.body, page.url),
  page.url,
  maxItems,
);
const checked = await mapConcurrent(
  normalized,
  enrichmentConcurrency,
  checkArticle,
);
return checked.filter((item) => item !== null);

const itemFiles = await Promise.all(items.map(async (item) => {
  const itemFile = path.join(stagingItemsPath, item.uid, "item.json");
  await writeJson(itemFile, item);
  return `items/${item.uid}/item.json`;
}));

await fs.rename(stagingItemsPath, itemsPath);
await writeJson(indexPath, {
  generatedAt: new Date().toISOString(),
  sources: sourceOptions,
  items: itemFiles,
});

const response = await fetch(
  `${informationIndexUrl.href}?v=${Date.now()}`,
  { cache: "no-store", headers: { accept: "application/json" } },
);
const manifest = await response.json();
items = await Promise.all(
  manifest.items.map((itemPath) => fetch(new URL(itemPath, informationIndexUrl)).then((item) => item.json())),
);
